/**
 * D764 (#2089) — the rail's model matrix, read.
 *
 * `railMatrix.json` is generated by `scripts/build-rail-matrix.mjs` from the
 * owner's canvas and never edited here: one row per page, its kind of work,
 * its router task and its models, default first. This file answers one
 * question, `resolveRail(page)`, and the two rules a pick is checked by.
 *
 * Pure: no `env`, no binding. `routes/ai.ts` calls it.
 */
import matrix from './railMatrix.json';

export type RailModel = { id: string; role: string; line: string };
export type RailRow = { pageKey: string; kind: string; routeTask: string; models: RailModel[] };

const ROWS: readonly RailRow[] = matrix.rows;
const BY_KEY = new Map(ROWS.map((r) => [r.pageKey.toLowerCase(), r]));

/** Every page row, in the canvas's order. */
export function railRows(): readonly RailRow[] {
  return ROWS;
}

/**
 * The page's row, matched without regard to case, so the stored section
 * (`ai_rail_preferences.section`, the page key lower-cased, D720 §6) finds it
 * too. Null for a page the matrix has no row for.
 */
export function resolveRail(page: string | null | undefined): RailRow | null {
  if (typeof page !== 'string') return null;
  return BY_KEY.get(page.trim().toLowerCase()) ?? null;
}

/** The preference section a page's picks and mode are stored under. */
export function railSectionOf(row: RailRow): string {
  return row.pageKey.toLowerCase();
}

/** The breadcrumb the rail draws: the page key's parts. */
export function railCrumbs(row: RailRow): string[] {
  return row.pageKey.split(' · ');
}

/** True when the row offers this model, the only picks a page accepts. */
export function rowOffers(row: RailRow, model: string): boolean {
  return row.models.some((m) => m.id === model);
}
